// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UpstreamConnection) predicate.UpstreamConnection {
	return predicate.UpstreamConnection(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UpstreamConnection) predicate.UpstreamConnection {
	return predicate.UpstreamConnection(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UpstreamConnection) predicate.UpstreamConnection {
	return predicate.UpstreamConnection(sql.NotPredicates(p))
}
